-- -----------------------------------------------------
-- procedure sp_CreateCalendarSchedule
-- -----------------------------------------------------

USE `ifamous_dbms`;
DROP procedure IF EXISTS `ifamous_dbms`.`sp_CreateCalendarSchedule`;

DELIMITER $$
USE `ifamous_dbms`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_CreateCalendarSchedule`(
    IN p_fyp_session_id INT,
    IN p_is_class TINYINT(1),
    IN p_owner_identifier VARCHAR(255),
    IN p_schedule_json JSON
)
BEGIN
    DECLARE v_session_exists INT DEFAULT 0;

    -- 1. Check if the session exists in the fyp_session table
    SELECT 1 INTO v_session_exists 
    FROM fyp_session 
    WHERE fyp_session_id = p_fyp_session_id LIMIT 1;

    -- 2. If it does not exist, throw a custom error immediately
    IF v_session_exists = 0 THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'Validation Error: The specified FYP Session does not exist.';
    ELSE
        -- 3. If it does exist, proceed with the insert
        INSERT INTO time_table (
            fyp_session_id, 
            is_class, 
            owner_identifier, 
            schedule_json
        ) 
        VALUES (
            p_fyp_session_id, 
            p_is_class, 
            p_owner_identifier, 
            p_schedule_json
        );
        
        -- Return the newly generated ID back to your backend
        SELECT LAST_INSERT_ID() AS new_time_table_id;
    END IF;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_DeleteCalendarSchedule
-- -----------------------------------------------------

USE `ifamous_dbms`;
DROP procedure IF EXISTS `ifamous_dbms`.`sp_DeleteCalendarSchedule`;

DELIMITER $$
USE `ifamous_dbms`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_DeleteCalendarSchedule`(
    IN p_time_table_id INT
)
BEGIN
    -- Deletes the specific schedule record
    DELETE FROM time_table 
    WHERE time_table_id = p_time_table_id;
    
    -- Return the number of affected rows to confirm success to the backend
    SELECT ROW_COUNT() AS affected_rows;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_GetSessionCalendarData
-- -----------------------------------------------------

USE `ifamous_dbms`;
DROP procedure IF EXISTS `ifamous_dbms`.`sp_GetSessionCalendarData`;

DELIMITER $$
USE `ifamous_dbms`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_GetSessionCalendarData`(IN p_session_id INT)
BEGIN
    -- Result Set 1: Verify the Session Exists
    SELECT fyp_session_id 
    FROM fyp_session 
    WHERE fyp_session_id = p_session_id;
    -- Result Set 2: Get all Timetables (Sections & Staff) for this session
    SELECT 
        time_table_id,
        is_class,
        owner_identifier,
        schedule_json
    FROM time_table 
    WHERE fyp_session_id = p_session_id;
   
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_SetActiveFYPSession
-- -----------------------------------------------------

USE `ifamous_dbms`;
DROP procedure IF EXISTS `ifamous_dbms`.`sp_SetActiveFYPSession`;

DELIMITER $$
USE `ifamous_dbms`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_SetActiveFYPSession`(
    IN p_target_session_id INT
)
BEGIN
    -- Updates all rows in the table. 
    -- If the ID matches the target, it becomes 1 (Active). 
    -- If it doesn't match, it becomes 0 (Inactive).
    UPDATE fyp_session 
    SET is_active = IF(fyp_session_id = p_target_session_id, 1, 0);
    
    -- Return the number of rows that were changed so the backend can verify
    SELECT ROW_COUNT() AS affected_rows;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_UpdateCalendarSchedule
-- -----------------------------------------------------

USE `ifamous_dbms`;
DROP procedure IF EXISTS `ifamous_dbms`.`sp_UpdateCalendarSchedule`;

DELIMITER $$
USE `ifamous_dbms`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_UpdateCalendarSchedule`(
    IN p_time_table_id INT,
    IN p_owner_identifier VARCHAR(255),
    IN p_schedule_json JSON
)
BEGIN
    -- Updates only the identifier and the JSON payload. 
    -- is_class is intentionally excluded to make it permanent.
    UPDATE time_table 
    SET 
        owner_identifier = p_owner_identifier,
        schedule_json = p_schedule_json
    WHERE 
        time_table_id = p_time_table_id;
        
    -- Return the number of affected rows to confirm success to the backend
    SELECT ROW_COUNT() AS affected_rows;
END$$

DELIMITER ;

