-- procedure sp_update_session
-- -----------------------------------------------------

USE `ifamous_dbms`;
DROP procedure IF EXISTS `ifamous_dbms`.`sp_update_session`;

DELIMITER $$
USE `ifamous_dbms`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_session`(
	IN old_session_id INT,
    IN new_session_id INT
)
BEGIN
	UPDATE fyp_session SET fyp_session_id = new_session_id 
    WHERE fyp_session_id = old_session_id;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- View `ifamous_dbms`.`vw_project_scheduling_roster`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `ifamous_dbms`.`vw_project_scheduling_roster`;
DROP VIEW IF EXISTS `ifamous_dbms`.`vw_project_scheduling_roster` ;
USE `ifamous_dbms`;
CREATE  OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `ifamous_dbms`.`vw_project_scheduling_roster` AS select `project`.`project_id` AS `project_id`,`project`.`fyp_session_id` AS `fyp_session_id`,`project`.`title` AS `project_title`,json_object('student_id',`project`.`student_id`,'full_name',`stu_user`.`full_name`,'metric_number',`s`.`metric_number`,'email',`stu_user`.`email`) AS `student_details`,json_object('supervisor_id',`project`.`supervisor_id`,'full_name',`sv_user`.`full_name`,'email',`sv_user`.`email`) AS `supervisor_details`,coalesce((select json_arrayagg(json_object('examiner_id',`ea`.`examiners_id`,'name',`ex_user`.`full_name`,'email',`ex_user`.`email`)) from (`ifamous_dbms`.`examine` `ea` join `ifamous_dbms`.`users` `ex_user` on((`ea`.`examiners_id` = `ex_user`.`user_id`))) where (`ea`.`project_id` = `project`.`project_id`)),json_array()) AS `examiners_json` from (((`ifamous_dbms`.`projects` `project` join `ifamous_dbms`.`students` `s` on((`project`.`student_id` = `s`.`student_id`))) join `ifamous_dbms`.`users` `stu_user` on((`project`.`student_id` = `stu_user`.`user_id`))) join `ifamous_dbms`.`users` `sv_user` on((`project`.`supervisor_id` = `sv_user`.`user_id`)));

SET SQL_MODE=@OLD_SQL_MODE;
SET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;
SET UNIQUE_CHECKS=@OLD_UNIQUE_CHECKS;
